/* ===== AUS simulator (DU / LPA / TOTAL-GUS) with credit-model toggle, Underwriter discretion & advocacy, VA Mastery course ===== */
function ausSimulate(a){
 const prog=a.prog,eng=a.engine;const f=+a.fico||0,ltv=+a.ltv||0,cltv=Math.max(ltv,+a.cltv||0),dti=+a.dti||0,res=+a.reserves||0,bk=+a.bkMonths||999,fc=+a.fcMonths||999,lates=+a.lates||0,coll=+a.coll||0,emp=+a.empMonths||0,resid=+a.residual||100;
 const risk=[],mit=[],msgs=[];let score=0; /* higher = riskier */
 /* score model adjustment (estimate only) */
 let f2=f;if(a.model==="vantage4"){f2=f+(a.thinFile==="y"?15:0)+(a.medColl==="y"?10:0)+(a.rentReport==="y"?12:0)-(a.trendUp==="n"?8:0)}else if(a.model==="fico10t"){f2=f+(a.trendUp==="y"?6:-10)+(a.rentReport==="y"?5:0)}
 if(f2<580)score+=40,risk.push("Credit score below 580");else if(f2<620)score+=25,risk.push("Score 580–619: below conventional minimum; FHA/VA manual territory");else if(f2<660)score+=14,risk.push("Score 620–659: thin margin on DU/LPA risk assessment");else if(f2<700)score+=7;else if(f2>=740)score-=8,mit.push("Score 740+ (strong)");
 if(dti>50)score+=22,risk.push(`DTI ${dti}% above 50%`);else if(dti>45)score+=12,risk.push(`DTI ${dti}% in 45–50% band`);else if(dti>36)score+=4;else score-=6,mit.push("DTI ≤36%");
 if(ltv>95)score+=10,risk.push("LTV above 95%");else if(ltv>90)score+=6;else if(ltv<=80)score-=8,mit.push("LTV ≤80%");
 if(cltv>ltv+5)score+=4,risk.push("Subordinate financing");
 if(res>=6)score-=10,mit.push(`${res} months reserves`);else if(res>=2)score-=4,mit.push(`${res} months reserves`);else if(res<1)score+=6,risk.push("No reserves");
 if(a.occ==="investment")score+=10,risk.push("Investment property");else if(a.occ==="second")score+=4;
 if(+a.units>1)score+=5,risk.push(`${a.units}-unit property`);
 if(a.ptype==="condo")score+=3;if(a.ptype==="manufactured")score+=8,risk.push("Manufactured home");
 if(a.purpose==="cashout")score+=10,risk.push("Cash-out refinance");
 if(a.selfemp==="y")score+=5,risk.push("Self-employed income");
 if(emp<24)score+=4,risk.push(`Employment history ${emp} months`);else if(emp>=60)score-=3,mit.push("5+ years employment");
 if(lates>=2)score+=18,risk.push(`${lates} mortgage/housing lates in 12 months`);else if(lates===1)score+=8,risk.push("1 housing late in 12 months");else mit.push("0×30 housing history");
 if(coll>5000)score+=10,risk.push(`Collections/charge-offs ${money(coll)}`);else if(coll>1000)score+=4;
 if(a.disputed==="y")score+=6,risk.push("Disputed derogatory tradelines");
 if(a.nontrad==="y")score+=12,risk.push("No usable credit score / non-traditional credit");
 if(a.fthb==="y")score+=2;if(a.gift==="y"&&ltv>95)score+=3;
 if(a.payShock>=50)score+=6,risk.push(`Payment shock ${a.payShock}%`);else if(a.payShock<=10)mit.push("Minimal payment shock");
 /* waiting periods */
 const W={conv:{bk7:48,bk13:24,fc:84,ss:48},fha:{bk7:24,bk13:12,fc:36,ss:36},va:{bk7:24,bk13:12,fc:24,ss:24},usda:{bk7:36,bk13:12,fc:36,ss:36}}[prog];
 const inelig=[];if(a.bkType==="7"&&bk<W.bk7)inelig.push(`Chapter 7 discharged ${bk} months ago; ${prog.toUpperCase()} requires ${W.bk7} (extenuating circumstances may shorten)`);if(a.bkType==="13"&&bk<W.bk13)inelig.push(`Chapter 13 ${bk} months; requires ${W.bk13} of plan payments/discharge`);if(fc<W.fc)inelig.push(`Foreclosure/DIL ${fc} months ago; requires ${W.fc}`);
 if(prog==="conv"&&f2<620)inelig.push("Score below 620 (conventional minimum)");if(prog==="conv"&&dti>50)inelig.push("DTI above 50% (DU/LPA hard cap)");if(prog==="conv"&&ltv>97)inelig.push("LTV above 97%");if(prog==="fha"&&f2<500)inelig.push("FHA requires 500+");if(prog==="fha"&&f2<580&&ltv>90)inelig.push("FHA 500–579 limited to 90% LTV");if(prog==="usda"&&dti>46)inelig.push("GUS unlikely above ~46% DTI without strong factors");if(prog==="usda"&&a.occ!=="primary")inelig.push("USDA primary only");if(prog==="va"&&a.occ!=="primary")inelig.push("VA requires owner occupancy");
 if(prog==="va"){if(resid<100)score+=20,risk.push(`Residual income ${resid}% of table`);else if(resid>=120)score-=10,mit.push(`Residual ${resid}% of table (≥120%)`);if(dti>41&&resid<120)risk.push("DTI >41% requires residual ≥120% or justification statement")}
 if(prog==="fha"&&(a.disputed==="y"||a.nontrad==="y"||lates>=1))msgs.push("TOTAL downgrade to manual underwriting likely (disputed accounts >$1,000, non-traditional credit, or recent housing lates)");
 /* engine flavor */
 let rec,label;const thr=eng==="lpa"?{a:22,c:40}:eng==="total"?{a:26,c:44}:{a:20,c:38};
 if(inelig.length)rec=eng==="lpa"?"Accept / Ineligible":eng==="total"?"Refer (ineligible)":"Approve / Ineligible",label="bad";
 else if(score<=thr.a)rec=eng==="lpa"?"Accept / Eligible":eng==="total"?"Accept / Eligible":"Approve / Eligible",label="good";
 else if(score<=thr.c)rec=eng==="lpa"?"Caution / Eligible":eng==="total"?"Refer / Eligible":"Approve / Eligible (expanded approval)",label="warn";
 else rec=eng==="lpa"?"Caution":eng==="total"?"Refer":"Refer with Caution",label="bad";
 if(prog==="va"&&eng!=="total")msgs.push("VA loans run through DU/LPA as 'VA' with Approve/Refer; residual income is always verified by the underwriter regardless of the AUS");
 if(ltv<=90&&a.purpose!=="cashout"&&a.ptype==="sfr"&&prog==="conv"&&score<=thr.a)msgs.push("Value acceptance (appraisal waiver) may be offered");
 if(res<2&&a.occ!=="primary")msgs.push(`Verify ${a.occ==="second"?2:6} months PITIA reserves`);
 if(a.selfemp==="y")msgs.push(eng==="du"&&emp>=60?"DU may require only the most recent year of returns (5+ years self-employed)":"Two years personal/business returns with YTD P&L");
 if(a.model!=="fico")msgs.push(`Estimated score under ${a.model==="vantage4"?"VantageScore 4.0":"FICO 10T"}: ${Math.round(f2)} (model adoption for agency loans is phasing in; lenders may still price on classic FICO)`);
 /* what to change */
 const fixes=[];if(dti>45)fixes.push(`Lower DTI to ≤45%: pay down ${money(Math.max(0,(dti-45)/100*(+a.income||8000)*10))} of revolving (≈ ${Math.round((dti-45))} pts) or seller-paid debt payoff (VA 4% concession)`);if(f2<660)fixes.push("Rapid rescore to the next tier (utilization <30%, authorized-user tradeline)");if(res<2)fixes.push("Document 2+ months reserves (retirement accounts count at 100% for conventional)");if(ltv>95&&prog==="conv")fixes.push("Add 2% down via gift or DPA to reach 95% (better MI and LLPA)");if(prog==="conv"&&(dti>50||f2<620))fixes.push("Switch program: FHA (DTI to 56.99%) or VA if eligible");if(prog==="va"&&resid<120&&dti>41)fixes.push("Raise residual: temporary buydown funded by seller, lower HOA property, or add non-taxable income (BAH/disability)");if(lates>=1)fixes.push("12 months clean housing history resets most AUS risk; LOE with cause and cure");
 return {rec,label,score:Math.round(score),risk,mit,msgs,inelig,fixes,f2:Math.round(f2)};
}
const AUS_PAGE_FIELDS=["prog","engine","model","fico","ltv","cltv","dti","reserves","occ","units","ptype","purpose","selfemp","empMonths","lates","coll","disputed","nontrad","fthb","gift","payShock","bkType","bkMonths","fcMonths","residual","income","thinFile","medColl","rentReport","trendUp"];
PAGE.aus={html:()=>`<div class="card"><h3>AUS Simulator <span class="sub">DU · LPA · FHA TOTAL / USDA GUS — a pre-flight estimate of the automated findings, the risk factors, and what to change before you run the real engine. Heuristic model, not Fannie/Freddie/HUD software.</span></h3>
<div class="grid g4">${sel("au_prog","Program",[["conv","Conventional"],["fha","FHA"],["va","VA"],["usda","USDA"]],"conv")}${sel("au_engine","Engine",[["du","DU (Fannie Mae)"],["lpa","LPA (Freddie Mac)"],["total","TOTAL Scorecard / GUS"]],"du")}${sel("au_model","Credit score model",[["fico","FICO classic 2/4/5 (today)"],["fico10t","FICO 10T (trended)"],["vantage4","VantageScore 4.0"]],"fico")}${numf("au_fico","Representative score",680,1)}
${numf("au_ltv","LTV %",96.5,0.5)}${numf("au_cltv","CLTV %",96.5,0.5)}${numf("au_dti","Back-end DTI %",46,0.5)}${numf("au_reserves","Reserves (months PITIA)",1,1)}
${sel("au_occ","Occupancy",[["primary","Primary"],["second","Second home"],["investment","Investment"]],"primary")}${sel("au_units","Units",[[1,"1"],[2,"2"],[3,"3"],[4,"4"]],1)}${sel("au_ptype","Property type",[["sfr","SFR / PUD"],["condo","Condo"],["manufactured","Manufactured"]],"sfr")}${sel("au_purpose","Purpose",[["purchase","Purchase"],["rt","Rate/term refi"],["cashout","Cash-out refi"]],"purchase")}
${sel("au_selfemp","Self-employed?",[["n","No"],["y","Yes"]],"n")}${numf("au_empMonths","Months employment history",36,1)}${numf("au_lates","Housing lates (12 mo)",0,1)}${numf("au_coll","Collections/charge-offs $",0,100)}
${sel("au_disputed","Disputed derogatory accounts?",[["n","No"],["y","Yes"]],"n")}${sel("au_nontrad","No score / non-traditional credit?",[["n","No"],["y","Yes"]],"n")}${sel("au_fthb","First-time buyer?",[["n","No"],["y","Yes"]],"n")}${sel("au_gift","Down payment from gift?",[["n","No"],["y","Yes"]],"n")}
${numf("au_payShock","Payment shock %",30,5)}${sel("au_bkType","Bankruptcy",[["none","None"],["7","Chapter 7"],["13","Chapter 13"]],"none")}${numf("au_bkMonths","Months since BK discharge",999,1)}${numf("au_fcMonths","Months since foreclosure/DIL/SS",999,1)}
${numf("au_residual","VA residual % of table",120,5)}${numf("au_income","Gross monthly income $",8000,100)}${sel("au_thinFile","Thin file (<3 tradelines)?",[["n","No"],["y","Yes"]],"n")}${sel("au_medColl","Medical collections only?",[["n","No"],["y","Yes"]],"n")}
${sel("au_rentReport","Rent reported to bureaus?",[["n","No"],["y","Yes"]],"n")}${sel("au_trendUp","Balances trending down (trended data)?",[["y","Yes"],["n","No"]],"y")}</div>
<div class="row" style="margin-top:8px"><button class="btn" id="au_go">Simulate</button><button class="btn ghost sm" id="au_all">Compare DU vs LPA vs TOTAL</button><button class="btn ghost sm" id="au_copy">Copy findings</button><button class="btn ghost sm" id="au_adv">Build advocacy memo from this</button><button class="btn ghost sm" id="au_coach">Ask the Coach</button></div></div><div id="au_out"></div>
<div class="card"><h3>How the real engines decide <span class="sub">what to know before you trust a finding</span></h3><div class="grid g3 sm">
<div><b>DU (Fannie Mae)</b><ul style="margin:4px 0 0 18px"><li>Risk assessment weighs credit history, DTI, LTV/CLTV, reserves, loan purpose, occupancy, property and borrower count; results: Approve/Eligible, Approve/Ineligible, Refer with Caution, Out of Scope.</li><li>Max 50% DTI; 97% LTV; 620 minimum; uses the average of borrowers' representative scores for eligibility (lowest for some lenders' pricing).</li><li>Messages are conditions: verify reserves, 1084 analysis, value acceptance, positive rent payment history (12 months bank data) can lift a Refer.</li></ul></div>
<div><b>LPA (Freddie Mac)</b><ul style="margin:4px 0 0 18px"><li>Risk class Accept or Caution plus purchase eligibility; Caution files can be manually underwritten (Caution/A-minus eligible).</li><li>Often more generous on student loans (0.5%), 43% occupying-borrower DTI with non-occupant co-borrowers, asset-and-income modeler (AIM) for cash flow, no-score borrowers.</li><li>Run both: lenders with dual AUS pick the better finding on the same data.</li></ul></div>
<div><b>TOTAL (FHA) / GUS (USDA)</b><ul style="margin:4px 0 0 18px"><li>Accept/Approve or Refer; FHA DTI to 56.99% with Accept; downgrade triggers (disputed >$1,000, lates, non-traditional credit, undisclosed debt) force manual underwriting at 31/43 → 40/50 with compensating factors.</li><li>GUS: Accept, Refer, Refer with Caution; 640+ for streamlined; income limits are household-based.</li><li>VA has no VA-built AUS: lenders run DU/LPA 'VA' with residual income verified manually.</li></ul></div></div>
<p class="sm mut" style="margin-top:8px"><b>Credit score models:</b> agency loans still use classic FICO 2/4/5 (middle of three) in 2026 while FHFA's move to FICO 10T and VantageScore 4.0 (both use trended data and rent/utility reporting, ignore paid collections and medical debt under $500) phases in. A borrower with on-time rent, declining balances and only medical collections typically scores 10–30 points higher under the new models; a borrower with rising balances scores lower. The simulator's model toggle estimates that shift.</p></div>`,
 mount(){const read=()=>Object.fromEntries(AUS_PAGE_FIELDS.map(k=>[k,$("#au_"+k).value]));const st=store.get("aus");if(st)Object.entries(st).forEach(([k,v])=>{const e=$("#au_"+k);if(e)e.value=v});
  const card=(a,r)=>`<div class="card" style="margin:0"><h3>${{du:"DU",lpa:"LPA",total:"TOTAL / GUS"}[a.engine]} · ${a.prog.toUpperCase()} <span class="tag ${r.label}">${esc(r.rec)}</span> <span class="mut sm">risk index ${r.score} · score used ${r.f2}</span></h3>
   ${r.inelig.length?`<div class="sm"><b>Ineligible:</b><ul style="margin:2px 0 6px 18px">${r.inelig.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>`:""}
   <div class="grid g2 sm"><div><b>Risk factors</b><ul style="margin:2px 0 0 18px">${r.risk.map(x=>`<li>${esc(x)}</li>`).join("")||"<li class='mut'>none flagged</li>"}</ul></div><div><b>Mitigants</b><ul style="margin:2px 0 0 18px">${r.mit.map(x=>`<li>${esc(x)}</li>`).join("")||"<li class='mut'>none</li>"}</ul></div></div>
   ${r.msgs.length?`<div class="sm" style="margin-top:6px"><b>Expected messages / conditions</b><ul style="margin:2px 0 0 18px">${r.msgs.map(x=>`<li>${esc(x)}</li>`).join("")}</ul></div>`:""}
   ${r.fixes.length?`<div class="sm" style="margin-top:6px"><b>What to change to improve the finding</b><ol style="margin:2px 0 0 18px">${r.fixes.map(x=>`<li>${esc(x)}</li>`).join("")}</ol></div>`:""}</div>`;
  let last=null;const go=(all)=>{const a=read();store.set("aus",a);const runs=all?["du","lpa","total"].map(e=>({...a,engine:e})):[a];last=runs.map(x=>({a:x,r:ausSimulate(x)}));$("#au_out").innerHTML=`<div class="grid ${all?"g3":"g1"}" style="margin-top:12px">${last.map(x=>card(x.a,x.r)).join("")}</div>`};
  $("#au_go").onclick=()=>go(false);$("#au_all").onclick=()=>go(true);
  $("#au_copy").onclick=()=>{if(!last)go(false);copy(last.map(({a,r})=>`${a.engine.toUpperCase()} ${a.prog.toUpperCase()}: ${r.rec} (risk index ${r.score})\nRisk: ${r.risk.join("; ")}\nMitigants: ${r.mit.join("; ")}\nConditions: ${r.msgs.join("; ")}\nFixes: ${r.fixes.join("; ")}`).join("\n\n"))};
  $("#au_adv").onclick=()=>{if(!last)go(false);const {a,r}=last[0];store.set("advSeed",{prog:a.prog,fico:a.fico,dti:a.dti,ltv:a.ltv,reserves:a.reserves,residual:a.residual,risk:r.risk,mit:r.mit});location.hash="uwadv"};
  $("#au_coach").onclick=()=>{const a=read();store.set("coachHist",[...store.get("coachHist",[]),`AUS pre-flight: ${a.prog} via ${a.engine}, score ${a.fico}, LTV ${a.ltv}, DTI ${a.dti}, reserves ${a.reserves} mo, ${a.occ}, lates ${a.lates}, collections ${a.coll}, BK ${a.bkType} ${a.bkMonths} mo, FC ${a.fcMonths} mo, residual ${a.residual}%. What finding should I expect, what will the underwriter condition, and the 4 best ways to strengthen it?`]);location.hash="coach"};
  if(st)go(false)}};

/* ---- Underwriter discretion & advocacy ---- */
const UW_DISCRETION=[
["Compensating factors on manual underwrites","FHA 4000.1 II.A.5.d; VA M26-7 Ch.4.10; Fannie B3-6-02","The underwriter can approve above standard ratios when documented factors exist: reserves (3+ months), minimal payment shock (≤5% or ≤$100), residual income above the VA table (FHA borrows the VA table), additional income not used, no discretionary debt, long employment, conservative credit use.","Present factors in a one-page narrative with the evidence tabbed (bank statements, LES, rent history). Quote the exact section and show the math."],
["Residual income 'as a general guide' (VA)","M26-7 Ch.4.9","VA says residual is a guide, not a cutoff: an underwriter may approve a veteran slightly below the table with strong factors, and must approve DTI >41% when residual ≥120% or a justification is written.","Compute residual at 120% target; if short, show non-taxable income, BAH continuance, low utilities, and a payment-shock table. Ask the underwriter to document the justification statement rather than decline."],
["Extenuating circumstances (waiting periods)","Fannie B3-5.3-08; 4000.1 II.A.5.a.iii; M26-7 Ch.4.7","One-time events beyond control (death, divorce, medical, job loss from plant closure) can cut BK/foreclosure waits (Fannie 7→3 years; FHA 2→1 year; VA 2→1 year) with proof the event caused the default and credit was re-established.","Build the timeline: event date, proof (death certificate, medical bills, layoff letter), default dates matching the event, and 12–24 months of clean credit after. LOE L-series letters in Letter Desk."],
["Credit exceptions: lates, collections, disputes","Lender credit policy; 4000.1 II.A.4.b.iv; M26-7 Ch.4.7","Isolated 30-day lates, medical collections, small unpaid collections and non-derogatory disputes are typically within the underwriter's discretion to accept with an LOE; patterns are not.","Isolate the event, show cause and cure, and offer to pay or exclude. Do not dispute accurate items; remove inaccurate ones via rapid rescore."],
["Income: declining, variable, new job, gaps","Fannie B3-3.1; 4000.1 II.A.4.c; M26-7 Ch.4.2","Underwriters may use 12-month averages for variable income with justification, accept new-job offer letters with a start before closing, and ignore gaps explained by school, military or childcare.","Provide the trend analysis (24-mo vs 12-mo vs YTD), employer letter on continuance, degree/training tying to the new role."],
["Student loans, co-signed and business debts","Fannie B3-6-05; 4000.1 II.A.4.b.iv(H); M26-7 Ch.4.5","Documented payments (IBR >$0), 12 months of third-party payment evidence, and business-paid debts can be excluded or reduced; VA excludes deferred student loans 12+ months.","Pull the servicer letter, 12 canceled checks, and business statements; show the DTI with and without."],
["Property condition and appraisal","M26-7 Ch.12; 4000.1 II.D; Fannie B4-1.3","The SAR/underwriter decides whether to accept unpermitted space, as-is conditions, cosmetic repairs, escrow holdbacks, and ROV outcomes.","Supply contractor bids, permits/final inspections, comps for ROV, and a repair escrow proposal (1.5× cost) when weather delays."],
["Assets: large deposits, gifts, business funds","Fannie B3-4.2; 4000.1 II.A.4.d","Underwriters may accept reasonable explanations for deposits, cash-flow analysis for business funds, and gifts from extended family or friends with a documented relationship (FHA).","Deposit sourcing table with dates, source, documents; CPA letter that withdrawal won't harm the business."],
["Occupancy and intent","M26-7 Ch.3.5; 4000.1 II.A.1.b.iii","The underwriter judges reasonableness: distance to work, family-size change, deployment, retirement timelines.","Write the occupancy LOE with the move date, commute logic, orders/retirement letters, utility setup plan."],
["Exceptions desk / credit policy overrides","Lender policy","Lenders have an exception process (regional UW manager → credit policy) for overlays, not for agency rules; brokers can also move the file to a lender without the overlay.","Ask the AE for the exception form, attach the narrative and AUS findings, and in parallel run the file at a no-overlay lender."],
["VA prior approval & RLC consult","M26-7 Ch.5; 877-827-3702","Non-automatic lenders, joint loans with non-spouse co-borrowers, and unusual files can be sent to VA for prior approval; the RLC loan technicians answer eligibility and underwriting questions by phone.","Call before submitting; document the technician's name/date; submit 26-1802a with the full package and the justification."],
];
PAGE.uwadv={html:()=>`<div class="card"><h3>Underwriter discretion &amp; advocacy <span class="sub">what the underwriter is allowed to decide, how to present it, and a memo generator that argues the file to pre-approval</span></h3>
<div class="grid g2"><div><h4>Discretion items (click for how to advocate)</h4>${UW_DISCRETION.map((d,i)=>`<details class="acc"><summary><b>${esc(d[0])}</b> <span class="mut sm">${esc(d[1])}</span></summary><div class="sm" style="padding:4px 0 8px"><p>${esc(d[2])}</p><p><b>Advocate:</b> ${esc(d[3])}</p></div></details>`).join("")}
<h4 style="margin-top:10px">Escalation ladder</h4><ol class="sm" style="margin:4px 0 0 18px"><li>Underwriter (reply to the condition with evidence, not argument).</li><li>Underwriting manager / second-level review (ask for a 'second look' with the narrative).</li><li>Credit policy / exceptions desk (for overlay exceptions only).</li><li>Alternative execution: lender without the overlay, program switch, or VA prior approval.</li><li>VA questions: Regional Loan Center ${VA_RLC_PHONE} (loan technicians, eligibility, appraisal). HUD FHA Resource Center 800-225-5342. USDA state office.</li></ol></div>
<div><h4>Advocacy memo builder</h4><div class="grid g2">${sel("ad_prog","Program",[["va","VA"],["fha","FHA"],["conv","Conventional"],["usda","USDA"],["nonqm","Non-QM"]],"va")}<div><label for="ad_name">Borrower</label><input id="ad_name" type="text" placeholder="e.g., SSgt J. Doe"></div>${numf("ad_fico","Score",640,1)}${numf("ad_dti","DTI %",52,0.5)}${numf("ad_ltv","LTV %",100,0.5)}${numf("ad_res","Reserves (months)",2,1)}${numf("ad_resid","Residual % of table (VA)",135,5)}<div><label for="ad_issue">Issues (one per line)</label><textarea id="ad_issue" rows="4" placeholder="DTI 52% driven by housing\n30-day late Mar 2025 (medical)\nCollections $1,800 (medical)"></textarea></div><div><label for="ad_comp">Compensating factors (one per line)</label><textarea id="ad_comp" rows="4" placeholder="Residual 135% of table\nBAH $3,100 non-taxable continuing\n11 years same employer\nPayment shock 4%"></textarea></div><div><label for="ad_ask">The ask</label><input id="ad_ask" type="text" value="Approve as submitted (Approve/Eligible with residual justification) and issue the pre-approval letter"></div></div>
<div class="row" style="margin-top:8px"><button class="btn" id="ad_go">Generate memo</button><button class="btn ghost sm" id="ad_copy">Copy</button><button class="btn ghost sm" id="ad_docx">⬇ Word</button><button class="btn ghost sm" id="ad_coach">Have the Coach strengthen it</button></div><pre id="ad_out" class="sm" style="white-space:pre-wrap;margin-top:8px;max-height:520px;overflow:auto"></pre></div></div></div>
<div class="card"><h3>Pre-approval advocacy checklist</h3><ol class="sm" style="margin:4px 0 0 18px"><li>Run the AUS Simulator, then the real DU and LPA (both) — take the better finding.</li><li>Pre-underwrite: income calc worksheet, residual, assets sourced, credit explained; nothing left for the underwriter to discover.</li><li>Write the narrative: 1 page, headed by the ask; issues → evidence → rule → factor; cite sections.</li><li>Tab the file (income, assets, credit, property, VA/FHA forms) and submit as a 'full pre-approval / TBD underwrite' so the approval is real before the offer.</li><li>Get the condition list in writing; respond to each condition with the document plus a one-line note.</li><li>If declined: request the specific rule or overlay in writing; separate agency rule from overlay; escalate or re-place within 24 hours; tell the client the plan the same day.</li></ol></div>`,
 mount(){const seed=store.get("advSeed");if(seed){$("#ad_prog").value=seed.prog;$("#ad_fico").value=seed.fico;$("#ad_dti").value=seed.dti;$("#ad_ltv").value=seed.ltv;$("#ad_res").value=seed.reserves;$("#ad_resid").value=seed.residual;$("#ad_issue").value=seed.risk.join("\n");$("#ad_comp").value=seed.mit.join("\n");store.set("advSeed",null)}
  const cite={va:"VA Pamphlet 26-7 Ch.4 (credit and income), Ch.4.9–4.10 (residual income, compensating factors)",fha:"HUD Handbook 4000.1 II.A.4–II.A.5 (manual underwriting, compensating factors)",conv:"Fannie Mae Selling Guide B3-5 (credit), B3-6 (liabilities), B3-4.1 (reserves); Freddie Mac Guide 5201–5401",usda:"USDA HB-1-3555 Ch.10–11 (credit, ratios, compensating factors)",nonqm:"Reg Z §1026.43(c) Ability-to-Repay factors; investor matrix"}[$("#ad_prog").value];
  const build=()=>{const n=$("#ad_name").value||"the borrower",p=$("#ad_prog").value.toUpperCase();const issues=$("#ad_issue").value.split("\n").filter(Boolean),comps=$("#ad_comp").value.split("\n").filter(Boolean);
   const t=`UNDERWRITING NARRATIVE AND REQUEST FOR APPROVAL\nBorrower: ${n}   Program: ${p}   Score: ${$("#ad_fico").value}   DTI: ${$("#ad_dti").value}%   LTV: ${$("#ad_ltv").value}%   Reserves: ${$("#ad_res").value} months${$("#ad_prog").value==="va"?`   Residual income: ${$("#ad_resid").value}% of the VA table`:""}\n\nTHE ASK\n${$("#ad_ask").value}\n\nSUMMARY\nThis file presents ${issues.length} item${issues.length===1?"":"s"} outside standard parameters, each explained and offset by documented compensating factors permitted under ${cite}. The layered risk is low: housing history is the strongest predictor of performance and is addressed below.\n\nISSUES, EVIDENCE AND RULE\n${issues.map((x,i)=>`${i+1}. ${x}\n   Evidence: [tab ${i+1}] ${/late|lates/i.test(x)?"LOE with cause and cure; 12-month payment history since":/collection/i.test(x)?"itemized collections with dates and type; medical items excluded per guideline; payoff or exclusion offered":/dti/i.test(x)?"income calculation worksheet; debt schedule; payment-shock analysis":/residual/i.test(x)?"residual income worksheet with actual tax withholding from LES/pay stubs":/bankruptcy|foreclosure|bk|fc/i.test(x)?"discharge/transfer documents, extenuating-circumstance proof and timeline, re-established credit":"supporting documents attached"}\n   Rule: ${cite}`).join("\n")}\n\nCOMPENSATING FACTORS\n${comps.map((x,i)=>`• ${x}`).join("\n")||"• (list factors)"}\n\nWHY THIS LOAN PERFORMS\n${$("#ad_prog").value==="va"?"VA guaranteed loans carry the lowest serious-delinquency rate of any program; residual income above the table is the single strongest VA predictor, and this borrower exceeds it.":"The borrower's housing payment history, reserves and payment-shock profile are the strongest predictors of performance and are favorable here."} Risk is not layered: the issues above share a single documented cause and do not recur.\n\nREQUESTED ACTION\n${$("#ad_ask").value}. If any condition remains, please specify the guideline section or lender overlay so we can satisfy it or escalate to second-level review.\n\nPrepared by: Steven Shearrill, MLO · Patriot Pacific Financial Corp · VA questions verified with the VA Regional Loan Center ${VA_RLC_PHONE}`;$("#ad_out").textContent=t;return t};
  $("#ad_go").onclick=build;$("#ad_copy").onclick=()=>copy(build());$("#ad_docx").onclick=()=>saveFile("underwriting-advocacy-memo.docx",docxBytes(build().split("\n").map(l=>({t:l,b:/^[A-Z ,]+$/.test(l)&&l.length>3?1:0}))));
  $("#ad_coach").onclick=()=>{store.set("coachHist",[...store.get("coachHist",[]),"Strengthen this underwriting advocacy memo; cite exact sections and add any compensating factor I missed:\n\n"+build()]);location.hash="coach"};
  if(seed)build()}};

